<?php declare(strict_types=1);use StudPulse\Config;use StudPulse\Database\DB;if(PHP_SAPI!=='cli'||($argv[1]??'')!=='--purge-expired'){if(PHP_SAPI==='cli')fwrite(STDERR,"Usage: php bin/maintenance.php --purge-expired\n");exit(1);}require dirname(__DIR__).'/app/bootstrap.php';$removed=DB::run('DELETE FROM rate_limits WHERE window_start<?',[time()-86400])->rowCount();foreach(['DELETE FROM bars_auth_flows WHERE expires_at<=UTC_TIMESTAMP(6)',"DELETE c FROM provider_credentials c JOIN provider_connections p ON p.id=c.connection_id WHERE p.provider='bars' AND c.expires_at<=UTC_TIMESTAMP(6)",'DELETE FROM login_links WHERE expires_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY)','DELETE FROM oauth_states WHERE expires_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY)','DELETE FROM idempotency_keys WHERE expires_at<UTC_TIMESTAMP(6)','DELETE FROM user_sessions WHERE expires_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY) OR revoked_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY)','DELETE p FROM push_subscriptions p LEFT JOIN user_sessions s ON s.id=p.session_id WHERE p.session_id IS NOT NULL AND s.id IS NULL','DELETE FROM notifications WHERE created_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 90 DAY)','DELETE FROM audit_events WHERE occurred_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 180 DAY)',]as$sql){$removed+=DB::run($sql)->rowCount();}$logs=0;foreach(['/logs/app-*.log'=>30,'/mail/*.json'=>1]as$pattern=>$days){foreach(glob(Config::storage().$pattern)?:[]as$path){if(filemtime($path)<time()-$days*86400&&unlink($path))$logs++;}}echo"Expired rows removed: $removed\nExpired logs removed: $logs\n";